  CONSTRAINT "chk_expenses_amount_not_zero" CHECK (amount <> 0),
  CONSTRAINT "chk_expenses_negative_only_correction" CHECK (amount > 0 or corrects_expense_id is not null),
  CONSTRAINT "chk_expenses_not_own_correction" CHECK (corrects_expense_id is null or corrects_expense_id <> id),
  CONSTRAINT "chk_expenses_unit_required" CHECK (source in ('api', 'log') or org_unit_id is not null),
  CONSTRAINT "chk_expenses_service_period_pair" CHECK ((service_period_start is null) = (service_period_end is null)),
  CONSTRAINT "chk_expenses_service_period" CHECK (service_period_end is null or service_period_end >= service_period_start),
  CONSTRAINT "chk_expenses_external_ref_account" CHECK (external_ref is null or provider_account_id is not null),
  CONSTRAINT "chk_expenses_sync_provenance" CHECK ((source in ('api', 'log')) = (sync_run_id is not null)),
  CONSTRAINT "chk_expenses_import_provenance" CHECK ((source = 'import') = (import_batch_id is not null))
);

CREATE TABLE "accounting_periods" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "fiscal_year" int NOT NULL,
  "period_year" int NOT NULL,
  "period_month" int NOT NULL,
  "status" period_status NOT NULL DEFAULT 'open',
  "closed_at" timestamptz,
  "closed_by" bigint,
  CONSTRAINT "chk_accounting_periods_month" CHECK (period_month between 1 and 12),
  CONSTRAINT "chk_accounting_periods_closed" CHECK ((status = 'closed') = (closed_at is not null))
);

CREATE TABLE "exchange_rates" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "from_currency" char(3) NOT NULL,
  "to_currency" char(3) NOT NULL,
  "rate" numeric(18,8) NOT NULL,
  "effective_from" date NOT NULL,
  "declared_by" bigint,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "chk_exchange_rates_rate" CHECK (rate > 0),
  CONSTRAINT "chk_exchange_rates_pair" CHECK (from_currency <> to_currency)
);

CREATE TABLE "detection_runs" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "data_date" date NOT NULL,
  "inactivity_threshold_days" int NOT NULL DEFAULT 60,
  "rule_version" varchar(20) NOT NULL,
  "status" run_status NOT NULL DEFAULT 'running',
  "started_at" timestamptz NOT NULL DEFAULT (now()),
  "finished_at" timestamptz,
  CONSTRAINT "chk_detection_runs_finished" CHECK ((status = 'running') = (finished_at is null))
);

CREATE TABLE "detection_results" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "detection_run_id" bigint NOT NULL,
  "license_plan_id" bigint NOT NULL,
  "org_unit_id" bigint,
  "check_type" detection_check NOT NULL,
  "outcome" detection_outcome NOT NULL,
  "flagged_qty" numeric(20,4),
  "monthly_cost" numeric(18,2),
  "currency" char(3),
  "flagged_since" date,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "chk_detection_results_unit" CHECK (check_type = 'inactive' or org_unit_id is not null),
  CONSTRAINT "chk_detection_results_not_evaluated" CHECK ((outcome = 'not_evaluated') = (flagged_qty is null)),
  CONSTRAINT "chk_detection_results_flagged" CHECK (outcome <> 'flagged' or flagged_qty > 0),
  CONSTRAINT "chk_detection_results_clear" CHECK (outcome <> 'clear' or flagged_qty = 0),
  CONSTRAINT "chk_detection_results_since" CHECK ((outcome = 'flagged') = (flagged_since is not null)),
  CONSTRAINT "chk_detection_results_currency" CHECK (monthly_cost is null or currency is not null)
);

CREATE TABLE "recommendations" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "license_plan_id" bigint NOT NULL,
  "target_plan_id" bigint,
  "org_unit_id" bigint,
  "detection_result_id" bigint,
  "type" recommendation_type NOT NULL,
  "title" varchar(300) NOT NULL,
  "description" text,
  "evidence" jsonb NOT NULL,
  "affected_qty" numeric(20,4),
  "estimated_yearly_saving" numeric(18,2),
  "actual_saving" numeric(18,2),
  "currency" char(3) NOT NULL,
  "status" recommendation_status NOT NULL DEFAULT 'proposed',
  "rejection_reason" text,
  "notice_deadline" date,
  "due_date" date,
  "owner_id" bigint,
  "created_by" bigint NOT NULL,
  "decided_by" bigint,
  "decided_at" timestamptz,
  "done_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "chk_recommendations_reject_reason" CHECK (status <> 'rejected' or rejection_reason is not null),
  CONSTRAINT "chk_recommendations_done" CHECK (status <> 'done' or (done_at is not null and actual_saving is not null)),
  CONSTRAINT "chk_recommendations_decided" CHECK ((status in ('accepted', 'rejected', 'done')) = (decided_at is not null)),
  CONSTRAINT "chk_recommendations_saving" CHECK (estimated_yearly_saving is null or estimated_yearly_saving >= 0),
  CONSTRAINT "chk_recommendations_target_plan" CHECK ((type = 'downgrade_plan') = (target_plan_id is not null)),
  CONSTRAINT "chk_recommendations_target_differs" CHECK (target_plan_id is null or target_plan_id <> license_plan_id)
);

CREATE TABLE "audit_logs" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "actor_id" bigint,
  "action" varchar(50) NOT NULL,
  "entity_type" varchar(60) NOT NULL,
  "entity_id" bigint NOT NULL,
  "old_values" jsonb,
  "new_values" jsonb,
  "reason" text,
  "correlation_id" varchar(64),
  "ip_address" varchar(45),
  "occurred_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "data_overrides" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "entity_type" varchar(60) NOT NULL,
  "entity_id" bigint NOT NULL,
  "field_name" varchar(60) NOT NULL,
  "original_value" text,
  "override_value" text NOT NULL,
  "reason" text NOT NULL,
  "overridden_by" bigint NOT NULL,
  "overridden_at" timestamptz NOT NULL DEFAULT (now()),
  "reverted_at" timestamptz
);

