COMMENT ON TABLE "org_units" IS 'P&Ls (subsidiaries) and their departments in one two-level tree (UC20).
A "unit" in the docs is one row of this table.
Partial unique: P&L names are unique, case-insensitive
(unique on lower(name) where parent_id is null).
App rule: the parent of a department is a P&L (with the check above this
also rules out deeper trees and cycles); a unit with active employees, an
active budget plan, or active plans it owns cannot be marked inactive.
';

COMMENT ON COLUMN "org_units"."parent_id" IS 'NULL for a P&L; the owning P&L for a department';

COMMENT ON COLUMN "org_units"."source" IS 'import = loaded from HR data; the name is then read-only (UC20)';

COMMENT ON COLUMN "org_units"."external_ref" IS 'Key of the unit in the HR source, if imported';

COMMENT ON TABLE "employees" IS 'Directory of real employees (decision D2). An employee may have no account.
Cost allocation, data scope, and "Unknown department" all read org_unit_id
here, never from the account. Only the current department is kept (D9):
past months keep their department through the frozen snapshots and
cost_allocations.
App rule: setting status to left disables the account of the employee in
the same transaction (D14).
';

COMMENT ON COLUMN "employees"."employee_code" IS 'HR code, if known';

COMMENT ON COLUMN "employees"."email" IS 'Company email, stored lowercase; the matching key for accounts and provider identities';

COMMENT ON COLUMN "employees"."org_unit_id" IS 'Department (or P&L when no department). NULL = Unknown department (BR-06)';

COMMENT ON COLUMN "employees"."external_ref" IS 'Key of the person in the HR or IdP source';

COMMENT ON TABLE "roles" IS 'The four fixed roles (BR-17). Seeded; UC21 changes the role of a user, not this list.';

COMMENT ON COLUMN "roles"."code" IS 'ADMIN, MANAGER, STAFF, EMPLOYEE';

COMMENT ON TABLE "permissions" IS 'Catalogue of what can be granted: feature x (read | write) (UC22). Seeded.';

COMMENT ON COLUMN "permissions"."feature_code" IS 'One per row of the role x feature matrix, e.g. contracts, expenses, budget_plan, recommendations';

COMMENT ON TABLE "role_permissions" IS 'Permission matrix; permissions belong to roles, never to single users (BR-17).
App rule: Employee cannot be granted price or cost features; the permission
Admin needs to manage permissions cannot be removed (UC22). Every change is
written to audit_logs with its reason.
';

COMMENT ON TABLE "user_accounts" IS 'Login accounts (UC19, UC21, UC24). Accounts are disabled, never deleted.
App rule: the last active Admin cannot be disabled or lose the Admin role;
an Admin cannot disable themselves (BR-17). An account of an employee with
status left cannot be re-enabled (D14). A role change away from MANAGER
removes the rows of the account in manager_org_units.
';

COMMENT ON COLUMN "user_accounts"."employee_id" IS 'Every account belongs to one employee; login email = employees.email';

COMMENT ON COLUMN "user_accounts"."role_id" IS 'Exactly one role per account (BR-17)';

COMMENT ON COLUMN "user_accounts"."password_hash" IS 'Hashed, never plain (BR-18). NULL until a first password is set; login is refused';

COMMENT ON COLUMN "user_accounts"."failed_login_count" IS 'Consecutive failures; reset on success';

COMMENT ON COLUMN "user_accounts"."locked_until" IS 'Set to now + 15 minutes after 5 failures in a row (BR-18)';

COMMENT ON COLUMN "user_accounts"."disabled_at" IS 'NULL = active. Set = disabled: cannot log in and open sessions are revoked (UC19); cleared on re-enable';

COMMENT ON TABLE "user_sessions" IS 'Server-side sessions, so disabling an account ends its open sessions at once
(UC19, BR-18). A new session id is issued at login (no session fixation);
expired and revoked rows are purged by a daily job. Cookie sessions need
CSRF protection (SameSite cookie plus a CSRF token on writes).
';

COMMENT ON COLUMN "user_sessions"."token_hash" IS 'SHA-256 of the session id kept in the HttpOnly, Secure cookie';

COMMENT ON COLUMN "user_sessions"."revoked_at" IS 'Set on logout, on disable, and on role change';

COMMENT ON TABLE "manager_org_units" IS 'Units a Manager is responsible for (UC20); the source of Manager data scope
(BR-16). A P&L assignment covers the departments under it.
App rule: the account has the MANAGER role.
';

COMMENT ON TABLE "system_settings" IS 'Global settings, seeded and changed only through a migration or by Admin:
  reporting_currency         VND (D12); budgets are in this currency
  inactivity_threshold_days  60 (BR-03)
  month_close_day            10: day of the next month a month closes (D14)
  raw_record_retention_days  180
';

COMMENT ON TABLE "vendors" IS 'Vendors / providers (UC02).
App rule: a vendor with an active contract cannot be marked inactive;
creating a vendor creates its default provider account.
';

COMMENT ON COLUMN "vendors"."collection_method" IS 'How this vendor data is normally collected (UC02)';

COMMENT ON TABLE "provider_accounts" IS 'One tenant, organization, or billing account at a provider (decision D11).
A group of companies often has one Microsoft 365 tenant per P&L; user ids,
subscription ids, and billing ids are unique only inside one account.
Every vendor has at least one account; a vendor without tenants has one
account named "Default".
';

COMMENT ON COLUMN "provider_accounts"."name" IS 'e.g. "Microsoft 365 - VinFast tenant"; "Default" for a vendor without tenants';

COMMENT ON COLUMN "provider_accounts"."tenant_ref" IS 'Tenant, organization, or billing account id at the provider';

COMMENT ON COLUMN "provider_accounts"."org_unit_id" IS 'P&L that owns the account, if one does';

COMMENT ON TABLE "software_categories" IS 'Category and subcategory in a two-level tree.
Partial unique: category names are unique where parent_id is null.
App rule: the parent of a subcategory is a category (parent_id is null).
';

COMMENT ON COLUMN "software_categories"."parent_id" IS 'NULL = category; set = subcategory of that category';

COMMENT ON TABLE "software_products" IS 'Software catalog (UC01), e.g. Microsoft 365. The "License" column of most
screens is this name; the "Plan" column is license_plans.name.
The migration makes the name unique case-insensitive (on lower(name)).
App rule: a product with an active entitlement line cannot be marked inactive.
';

COMMENT ON COLUMN "software_products"."category_id" IS 'Most specific node (subcategory if any). NULL is shown as Uncategorized';

COMMENT ON TABLE "product_links" IS 'Useful links of a product (UC01): policy, terms of service, admin portal.';

COMMENT ON TABLE "license_plans" IS 'The unit everything else calls "a license" (decision D1): one tier of a
product with one archetype and one unit. It stays the same across renewals,
so holders, usage, budget lines, expenses, and recommendations survive a
renewal. Purchased = sum of the entitlement lines of the plan that are
active on that day (see entitlement_lines).
Holders and usage are kept per plan, not per line (D1): providers pool the
seats of several purchases.
The owner unit (D10) is usually the P&L or IT department that buys the
license; Managers of that unit see its unassigned seats, overuse, and
holders with Unknown department. The migration makes the name unique
case-insensitive (on product_id, lower(name)).
';

COMMENT ON COLUMN "license_plans"."name" IS 'Tier / SKU name, e.g. E3, E5, Business, API pay-as-you-go';

COMMENT ON COLUMN "license_plans"."archetype" IS 'Measurement archetype (BR-02); every entitlement line of the plan inherits it';

COMMENT ON COLUMN "license_plans"."unit" IS 'What is counted: seat, device, slot, token, credit, GB, core ...';

COMMENT ON COLUMN "license_plans"."owner_org_unit_id" IS 'Unit that owns the license: receives its company-level results (D10)';

COMMENT ON TABLE "contracts" IS 'Contracts (UC04). A contract is active on a day when start_date <= day and
ended_on is null or later; there is no status column.
Computed, not stored:
  Notice deadline       = renewal_date - notice_period_days: the last day to
                          tell the vendor before an auto-renewal (UC13)
  Renewal soon          = renewal_date within 30 days
  Notice period passed  = today > notice deadline
Renewal dates feed the forecast (UC09) and recommendation timing (UC13).
';

COMMENT ON COLUMN "contracts"."contract_no" IS 'Number on the vendor paper, if any';

COMMENT ON COLUMN "contracts"."commitment_amount" IS 'Minimum commitment of the agreement, if any';

COMMENT ON COLUMN "contracts"."ended_on" IS 'NULL = not ended. Set by "mark ended" (UC04)';

COMMENT ON TABLE "entitlement_lines" IS 'One purchase of a plan (UC03): quantity, validity, and price terms.
A renewal or an extra purchase is a new line under the same plan.
A line is active on a day when valid_from <= day and (valid_to is null or
valid_to >= day). There is no status column: ending a line sets valid_to.
A renewal starts the day after the line it renews ends, so the boundary day
is never counted twice.
unit_price and effective monthly cost (BR-05) by commercial term:
  monthly            price per unit per month       quantity x unit_price
  yearly, multi_year price per unit per year        quantity x unit_price / 12
  perpetual          maintenance per unit per year  quantity x unit_price / 12
  prepaid_credit     price per credit               quantity x unit_price /
                                                    months of validity
  pay_as_you_go      reference rate per unit        actual spend of the
                                                    month from expenses
Quarterly payment is entered as its yearly price.
Partial unique: one line per subscription at the provider
(unique on provider_account_id, external_ref where external_ref is not null),
so a re-run sync updates the line instead of adding one (A3).
App rule: the vendor of the account and of the contract equals the vendor
of the plan product; a renewal line belongs to the same plan and starts
after the renewed line ends. A connector value edited by Staff needs a row
in data_overrides (BR-14).
';

COMMENT ON COLUMN "entitlement_lines"."provider_account_id" IS 'Account the purchase belongs to (D11)';

COMMENT ON COLUMN "entitlement_lines"."contract_id" IS 'Contract covering this line; one FK means a line is never under two contracts (UC04)';

COMMENT ON COLUMN "entitlement_lines"."renews_line_id" IS 'The line this one renews, if any; keeps the renewal chain';

COMMENT ON COLUMN "entitlement_lines"."quantity" IS 'Purchased quantity or quota. NULL = Unknown, unless is_unlimited';

COMMENT ON COLUMN "entitlement_lines"."is_unlimited" IS 'True for a line bought without a quota (e.g. metered pay-as-you-go): quantity is NULL and the line can never be over-used (BR-07)';

COMMENT ON COLUMN "entitlement_lines"."valid_to" IS 'Last day of validity, inclusive. NULL = open-ended (perpetual). "End a line" (UC03) sets this date';

COMMENT ON COLUMN "entitlement_lines"."commercial_term" IS 'The one field for how the line is paid (BR-02); it also fixes the period of unit_price';

COMMENT ON COLUMN "entitlement_lines"."unit_price" IS 'Price of one unit for the period of the commercial term (see table note). NULL = Unknown';

COMMENT ON COLUMN "entitlement_lines"."source" IS 'Source of quantity and validity (BR-14); prices always come from Staff';

COMMENT ON COLUMN "entitlement_lines"."external_ref" IS 'Subscription id at the provider, if synced';

COMMENT ON TABLE "entitlement_allocations" IS 'Optional quota of a purchase per unit (decision D3); gives the "Purchased"
level per unit in budget monitoring (UC08, BR-09) and the unit of its
unassigned seats (D10).
A line with no rows is shared: its seats belong to the owner unit of the
plan for detection, and no "Unassigned" gap is flagged per unit (BR-04).
Quotas apply for the whole validity of the line; a different split is a new
line. History per day is kept in plan_unit_daily_snapshots.
App rule: quotas are allowed only on a line with a known quantity that is
not unlimited, and add up to at most that quantity; the service locks the
line row (SELECT ... FOR UPDATE) before checking, so two concurrent changes
cannot exceed it.
';

COMMENT ON TABLE "connectors" IS 'One read-only connection to one provider account. The Admin configuration
screen is a later phase (docs/01 section 7), so rows are seeded for now.
';

COMMENT ON COLUMN "connectors"."connector_type" IS 'Implementation key, e.g. ms_graph, license_server_log; it also says whether the connector reads an API or a log';

COMMENT ON COLUMN "connectors"."credentials_ref" IS 'Reference to the secret in the secret store, or the credentials encrypted with a key kept outside the database; read-only scopes only (A8)';

COMMENT ON COLUMN "connectors"."schedule_cron" IS 'Daily by default (A1)';

COMMENT ON COLUMN "connectors"."is_simulated" IS 'True when the connector reads a fake provider, so figures are not presented as real (A9)';

COMMENT ON TABLE "plan_data_sources" IS 'The one primary source of each kind of data for a plan in one provider
account (BR-14).
- A plan whose assignment or usage source is a connector refuses manual
  entry and import of that data (UC03).
- A plan with no "usage" row for an account, or with an aggregate one, has
  no per-seat usage there: its seats are "Not monitored" (BR-03, D7) and
  are never counted as waste (BR-04).
App rule: the connector reads the same provider account.
';

COMMENT ON COLUMN "plan_data_sources"."source_type" IS 'Stamped as source on every row collected for this plan, account, and kind of data';

COMMENT ON COLUMN "plan_data_sources"."connector_id" IS 'Required when source_type is api or log';

COMMENT ON COLUMN "plan_data_sources"."external_ref" IS 'Key of the plan at the provider, e.g. Microsoft Graph skuId';

COMMENT ON COLUMN "plan_data_sources"."granularity" IS 'Required for usage: per subject or aggregate only';

COMMENT ON COLUMN "plan_data_sources"."monitoring_since" IS 'First day this source delivered data; Inactive needs a full threshold of monitoring (D7)';

COMMENT ON TABLE "sync_runs" IS 'One execution of a connector. A failed run writes no figures, so that day
stays Unknown instead of 0 (A4, BR-04); the next run catches up (A3).
Which plans a run covered completely is in collection_coverage.
A backfill writes one run per data date.
';

COMMENT ON COLUMN "sync_runs"."data_date" IS 'The day the collected figures describe (reports lag 1-2 days)';

COMMENT ON COLUMN "sync_runs"."window_start" IS 'Incremental window (A3)';

COMMENT ON TABLE "collection_coverage" IS 'Whether the connector data of a plan, account, and kind is complete for a
day (decision D8). A connector run writes one row per plan and kind it
collects; a later run of the same day replaces the row.
No row, partial, or failed = Unknown for that day: detection reports
not_evaluated (UC10-UC12, UC17) and daily snapshots are not written.
A successful run that finds 0 holders writes complete, so a true 0 is
told apart from a missing day.
Manual and imported data has no daily coverage: it is as of its last entry
or confirmed import, with low or medium confidence (BR-14).
';

COMMENT ON COLUMN "collection_coverage"."sync_run_id" IS 'Latest run that wrote this day';

COMMENT ON TABLE "raw_records" IS 'Raw provider data kept before normalization, so rules can change and be
recomputed without calling the API again (A2).
Payloads hold personal data (names, emails): only the collection service
reads this table, and rows older than raw_record_retention_days
(system_settings) are deleted. Idempotency is ensured by the unique keys of
the normalized tables, not by payload_hash.
';

COMMENT ON COLUMN "raw_records"."record_type" IS 'Provider object, e.g. subscribedSku, user, activeUserDetail';

COMMENT ON COLUMN "raw_records"."payload_hash" IS 'SHA-256 of the payload, to skip normalizing unchanged records';

COMMENT ON COLUMN "raw_records"."normalized_at" IS 'NULL until normalized into the tables below';

COMMENT ON TABLE "files" IS 'Uploaded files: contract attachments, expense invoices (PDF or image, at
most 10 MB, BR-10), and CSV import files. The service checks the content
type from the bytes, not from the name; files are served only through the
API with the permission of the row they belong to.
';

COMMENT ON COLUMN "files"."storage_key" IS 'Path or object key in file storage; the bytes are not in the database';

COMMENT ON COLUMN "files"."checksum" IS 'SHA-256 of the content';

COMMENT ON TABLE "import_batches" IS 'One CSV import by Staff: preview, then confirm (UC03, UC07). This is the
entry history "who, when, file, rows". One invalid row rejects the file.
App rule: confirm re-validates the same file (checksum) against the current
data and refuses when the preview is older than 1 hour or the plan has
gained a connector source since.
';

COMMENT ON COLUMN "import_batches"."license_plan_id" IS 'Set for assignment and usage imports, which target one plan';

COMMENT ON COLUMN "import_batches"."provider_account_id" IS 'Set for assignment and usage imports: the account the holders belong to';

COMMENT ON COLUMN "import_batches"."error_report" IS 'Rejected rows with their errors';

COMMENT ON TABLE "subjects" IS 'Who or what uses a license on the provider side: a user account, a device,
a project, an API key. Kept apart from employees because a provider identity
may match no employee (UC03, UC11).
Department of a subject = employees.org_unit_id for a matched user,
otherwise subjects.org_unit_id, otherwise Unknown department.
Partial unique: unique on provider_account_id, external_id where external_id
is not null; a sync matches on external_id first, so a renamed user keeps
the same subject and seat history.
Matching to an employee uses the company email first; Staff can confirm a
match by hand for an alias or a UPN that differs from the email.
';

COMMENT ON COLUMN "subjects"."provider_account_id" IS 'Identities are unique per account (D11)';

COMMENT ON COLUMN "subjects"."identifier" IS 'Provider identity, lowercase: email / userPrincipalName, device name, project, key label';

COMMENT ON COLUMN "subjects"."external_id" IS 'Immutable id at the provider, if any; survives a rename of the identifier';

COMMENT ON COLUMN "subjects"."employee_id" IS 'Only for user subjects. Matched by company email. NULL = not matched: shown with the provider identity and Unknown department';

COMMENT ON COLUMN "subjects"."org_unit_id" IS 'Only for non-person subjects (project, key, device pool) whose department is known (UC06)';

COMMENT ON COLUMN "subjects"."is_enabled" IS 'Account enabled at the provider; NULL = Unknown';

COMMENT ON TABLE "license_assignments" IS 'A holder of a plan: "Assigned" data read from the provider or entered by
Staff; ELMS never assigns or revokes (BR-01). An ended assignment keeps its
row.
Partial unique: one open assignment per plan and subject
(unique on license_plan_id, subject_id where ended_on is null).
Seat status (BR-03, D7) is computed, not stored, for an open assignment.
S = the usage source of the plan for the account of the subject,
T = inactivity_threshold_days (60):
  Not monitored = no S, or S.granularity = aggregate
  Active        = last_active_at within the last T days
  Inactive      = last_active_at older than T days
  No activity   = last_active_at is null
Detection (UC11) flags Inactive and No activity only when, on the data
date, the usage coverage is complete, S.monitoring_since is at least T days
old, and the seat has been held for at least T days (from assigned_on, or
first_seen_on when unknown). A new seat is not waste yet.
Unassigned = purchased quantity minus open assignments.
Expiry date of a seat (UC23) and its contract (UC13):
  entitlement_line_id set  = valid_to and contract of that line
  entitlement_line_id NULL = the earliest valid_to among the active lines
                             of the plan in the account, the first day the
                             seat may lapse
App rule: the line belongs to the same plan and the same provider account
as the subject.
';

COMMENT ON COLUMN "license_assignments"."entitlement_line_id" IS 'Purchase the seat belongs to. Set on Staff entry and by a sync when the plan has one active line in the account. NULL = not known: the provider pools the seats of several purchases';

COMMENT ON COLUMN "license_assignments"."assigned_on" IS 'Assigned date reported by the provider or entered by Staff; NULL = Unknown';

COMMENT ON COLUMN "license_assignments"."first_seen_on" IS 'First day ELMS saw the assignment';

COMMENT ON COLUMN "license_assignments"."ended_on" IS 'NULL = currently assigned';

COMMENT ON COLUMN "license_assignments"."last_active_at" IS 'Last recorded activity; NULL = no activity recorded. Only filled from a per-subject usage source';

COMMENT ON TABLE "usage_records" IS 'Usage per period for Concurrent, Metered, and Capacity plans, and aggregate
activity for Allocation plans without per-user data. Per-user activity of a
seat lives in license_assignments.last_active_at.
Entering the same period again replaces the row (UC03): the unique index
must be created with NULLS NOT DISTINCT so it also holds for aggregate rows,
where subject_id is NULL.
App rule: one period length per plan, account, and metric (the period of
the source, usually a day or a month) and no overlapping periods, so sums
over periods never count a day twice. The metric matches the archetype of
the plan (see the enum notes).
Metered overuse (D13) = sum of consumption over the validity of a line
with a quota, compared with that quota.
A missing period is Unknown, never 0 (BR-04).
';

COMMENT ON COLUMN "usage_records"."subject_id" IS 'NULL = aggregate figure for the whole plan in the account';

COMMENT ON COLUMN "usage_records"."period_end" IS 'Inclusive';

COMMENT ON TABLE "plan_daily_snapshots" IS 'Daily Purchased and cost per plan, kept by ELMS because providers give no
history (docs/01 section 4.4) and because a sync or a Staff correction
overwrites the quantity of a line, so past days cannot be recomputed from
entitlement_lines. Feeds trends, the forecast, and cost_allocations.
Rows are frozen once written; a later rate or price correction changes only
new days (D9, D12). Amounts are converted with the latest exchange rate
whose effective_from is on or before the snapshot date.
effective_monthly_cost is a monthly rate, not a daily amount: the cost of a
month = sum over its days of effective_monthly_cost / days in the month.
Never add up the daily rows as they are.
Assigned and Used are not stored here, so each figure has one owner:
seat counts are the sum over units of plan_unit_daily_snapshots; peak,
consumption, and deployed units of non-seat plans are in usage_records.
No row or a NULL column = Unknown for that day.
';

COMMENT ON COLUMN "plan_daily_snapshots"."purchased_qty" IS 'Sum of the entitlement lines active that day; NULL = Unknown (one active line Unknown makes the sum Unknown), or unlimited';

COMMENT ON COLUMN "plan_daily_snapshots"."is_unlimited" IS 'True when an active line of the plan is unlimited; purchased_qty is then NULL';

COMMENT ON COLUMN "plan_daily_snapshots"."effective_monthly_cost" IS 'BR-05 cost of a full month at the terms in force that day, in the reporting currency; NULL = Unknown (price or exchange rate missing)';

COMMENT ON COLUMN "plan_daily_snapshots"."currency" IS 'Reporting currency (D12)';

COMMENT ON TABLE "plan_unit_daily_snapshots" IS 'Daily seat status per plan and department: every assigned seat has exactly
one status (BR-03), so the four counts add up to assigned_count. The
department is the one of that day, so history keeps it after an employee
moves (D9).
Feeds the monthly usage charts, "Assigned" / "Used" per unit (BR-09), and
the seat basis of cost_allocations.
The unique index needs NULLS NOT DISTINCT because org_unit_id may be NULL.
Rows are written only for a day whose assignment coverage is complete in
every account of the plan (D8); counts have no default, so a missing day is
no row, never a row of zeros.
';

COMMENT ON COLUMN "plan_unit_daily_snapshots"."org_unit_id" IS 'Department of the holders that day; NULL = Unknown department';

COMMENT ON COLUMN "plan_unit_daily_snapshots"."used_qty" IS 'Non-seat plans: consumption or peak attributed to the unit; NULL = Unknown';

COMMENT ON TABLE "budget_plans" IS 'Yearly license budget of one unit (UC05, BR-08, decision D4): at most one
plan per unit and fiscal year; only active plans count.
P&L and department plans are two separate levels and are never added
together (UC08, UC16): a P&L plan is the envelope for the whole P&L, the
plans of its departments are shares inside it.
  Company total = the P&L plans; for a P&L without its own plan, the sum
                  of its department plans.
  Inside a P&L  = P&L budget minus the sum of its department budgets is
                  shown as "Not distributed".
Actual cost against the budget = the cost_allocations of the unit in the
fiscal year (effective, allocated view, D5); for a P&L, its own rows plus
those of its departments.
App rule: activation shows a warning and needs confirmation when the plan
lines add up to more than the budget, or when the department budgets of a
P&L add up to more than the P&L budget (UC05).
App rule: only a draft can be deleted. A change to an active plan needs a
reason and is written to audit_logs with old and new value (BR-08).
App rule: the currency is the reporting currency.
';

COMMENT ON COLUMN "budget_plans"."currency" IS 'Reporting currency (D12)';

COMMENT ON TABLE "budget_plan_lines" IS 'Plan lines: the "Planned" level of the reconciliation chain Planned -> Purchased -> Assigned -> Used -> Actual cost (BR-09).';

COMMENT ON COLUMN "budget_plan_lines"."planned_cost" IS 'In the currency of the budget plan; suggested = quantity x current yearly unit price, converted with the current rate';

COMMENT ON TABLE "cost_allocations" IS 'Effective cost of a plan for one month, split to units (UC06, BR-06,
decision D5). Source of "cost per department" (UC06, UC16) and of the
actual cost in budget monitoring (UC08).
Plan cost of the month:
  fixed terms     sum over the days of plan_daily_snapshots
                  .effective_monthly_cost / days in the month
  pay_as_you_go   expenses of the plan whose service period (or date)
                  falls in the month
Split, by method:
  per_seat   cost / average purchased seats x average seats of the unit
             (plan_unit_daily_snapshots); unheld seats go to unallocated,
             holders without department to unknown_department
  per_usage  by the usage of subjects with a known department; the rest
             is unallocated
  direct     pay-as-you-go expenses that name a unit go to that unit; the
             rest is unallocated
  none       the whole cost is unallocated
The rows of a plan and month add up to the plan cost (UC06 result).
Rows of an open month are recomputed daily; on month close they are
computed once more and marked final, so a later move of an employee, a
corrected rate, or a changed rule never rewrites a closed month (D9).
The unique index needs NULLS NOT DISTINCT because org_unit_id may be NULL.
';

COMMENT ON COLUMN "cost_allocations"."org_unit_id" IS 'Set when bucket = unit';

COMMENT ON COLUMN "cost_allocations"."basis_qty" IS 'Average seats held (per_seat) or usage (per_usage) of the bucket in the month; NULL for direct and none';

COMMENT ON COLUMN "cost_allocations"."amount" IS 'Share of the plan cost of the month; NULL = Unknown (price, rate, or seat data missing)';

COMMENT ON COLUMN "cost_allocations"."currency" IS 'Reporting currency (D12)';

COMMENT ON COLUMN "cost_allocations"."is_final" IS 'Set when the month closes; a final row is never recomputed';

COMMENT ON TABLE "expenses" IS 'Expenses and invoices (UC07): the billed cost view (D5), used for invoice
reconciliation, cash, and the "Billed" figures of the financial dashboard.
The vendor is read through the plan and product.
A prepaid invoice stays on its expense_date; its spread over months is the
effective cost of the entitlement line, not a split of this row (D6).
Pay-as-you-go expenses are also the cost source of cost_allocations.
Partial unique: one row per billing record
(unique on provider_account_id, external_ref where external_ref is not null).
App rule: an expense is editable until its month is closed
(accounting_periods); afterwards only a correcting entry is allowed, and it
is dated in an open month. An expense that came from a billing API needs a
reason to be edited (BR-14).
';

COMMENT ON COLUMN "expenses"."expense_date" IS 'Invoice or charge date; decides the closed month (BR-10)';

COMMENT ON COLUMN "expenses"."service_period_start" IS 'First day of the service the expense pays for, if known (D6)';

COMMENT ON COLUMN "expenses"."service_period_end" IS 'Last day of that service, inclusive';

COMMENT ON COLUMN "expenses"."amount" IS 'Positive; only a correcting entry may be negative';

COMMENT ON COLUMN "expenses"."org_unit_id" IS 'Unit that pays the invoice (BR-10). Required on manual entry and CSV; NULL only for billing API rows without a unit, shown as Unallocated';

COMMENT ON COLUMN "expenses"."corrects_expense_id" IS 'Set on a correcting entry for an expense of a closed month (BR-10)';

COMMENT ON COLUMN "expenses"."provider_account_id" IS 'Billing account the record came from; set for api rows';

COMMENT ON COLUMN "expenses"."external_ref" IS 'Id of the billing record at the provider, for idempotent sync (A3)';

COMMENT ON TABLE "accounting_periods" IS 'Calendar months and whether they are closed. A closed month locks its
expenses (BR-10), freezes its cost_allocations (D9), and counts as a
"closed month" for the forecast run rate (BR-11). fiscal_year maps the
month to a budget year.
Closing (D14): a system job closes month M on month_close_day of M+1
(system_settings, default the 10th); Staff can close it earlier. A closed
month is never reopened; later changes are correcting entries.
';

COMMENT ON COLUMN "accounting_periods"."closed_by" IS 'NULL when closed by the system job';

COMMENT ON TABLE "exchange_rates" IS 'Declared exchange rates (BR-05, D12), always toward the reporting currency.
The rate of a day = the row with the latest effective_from on or before that
day. Without a rate, converted figures are Unknown and amounts are shown per
currency, never added (UC16).
A corrected rate changes only figures not yet frozen; frozen snapshots and
final cost_allocations keep the rate they were computed with.
';

COMMENT ON COLUMN "exchange_rates"."rate" IS '1 from_currency = rate to_currency';

COMMENT ON TABLE "detection_runs" IS 'One daily detection run (BR-12). A re-run for the same data date adds a new run; screens read the latest successful run.';

COMMENT ON COLUMN "detection_runs"."data_date" IS 'Date of the data the run evaluated';

COMMENT ON COLUMN "detection_runs"."inactivity_threshold_days" IS 'Copied from system_settings so old results stay explainable';

COMMENT ON COLUMN "detection_runs"."rule_version" IS 'Version of the detection rules, e.g. 2026.11';

COMMENT ON TABLE "detection_results" IS 'Result of one check for one plan and unit in one run: only the verdict is
stored (outcome, flagged quantity, its cost, since when).
Unit of a result (D10):
  unused   one row per unit with a quota (quota minus its holders), and one
           row for the owner unit of the plan for the shared seats
  overuse  one row for the owner unit of the plan
  inactive one row per department of the holders; NULL = Unknown department
Manager data scope (BR-16): a Manager sees the rows of their units, plus the
Unknown-department rows of the plans their units own. No figure of another
unit is shown.
Lists, dashboards, and the compliance view read the same rows, so figures
tie across screens (UC10, UC12, UC17, UC18).
not_evaluated when the coverage of the data date is not complete (D8), or
the figures needed are Unknown.
The figures shown beside a result are read from their owner table for the
data date of the run, never copied here:
  Purchased / Entitlement = plan_daily_snapshots.purchased_qty
                            (or the quota of the unit)
  Assigned, seat statuses = plan_unit_daily_snapshots
  Peak, deployed units    = usage_records
  Unassigned, Excess      = flagged_qty
Evidence (BR-12) = these figures, last activity from license_assignments,
and the data date. The per-seat list of UC11 is the current list of
license_assignments: it is shown for the latest run only; older runs keep
their counts, not the names.
Saving opportunities (UC13) are computed from the latest results and the
contract dates; they are not stored until turned into a recommendation.
The unique index needs NULLS NOT DISTINCT because org_unit_id may be NULL.
';

COMMENT ON COLUMN "detection_results"."org_unit_id" IS 'Unit the result belongs to (D10). NULL only for inactive seats of holders with Unknown department';

COMMENT ON COLUMN "detection_results"."flagged_qty" IS 'Unassigned seats, inactive seats, or excess over the entitlement; 0 when clear; NULL when not evaluated';

COMMENT ON COLUMN "detection_results"."monthly_cost" IS 'Monthly cost of the flagged quantity; NULL = Unknown';

COMMENT ON COLUMN "detection_results"."flagged_since" IS 'First day of the current unbroken flagged streak ("Since", UC12)';

COMMENT ON TABLE "recommendations" IS 'Recommendations and their decision (UC14, BR-13):
proposed -> accepted or rejected (reason required) -> done (actual saving
required). ELMS never carries one out on the provider (BR-01).
An Unknown estimated saving is shown as Unknown and left out of saving
totals, which count it separately (D15).
Partial unique: one open recommendation per plan, type, and unit
(unique on license_plan_id, type, org_unit_id where status in
(proposed, accepted), with NULLS NOT DISTINCT).
App rule: only an accepted recommendation can be marked done; the target
plan belongs to the same product.
';

COMMENT ON COLUMN "recommendations"."target_plan_id" IS 'For downgrade_plan: the plan to move to, of the same product';

COMMENT ON COLUMN "recommendations"."org_unit_id" IS 'Unit the recommendation concerns, for Manager data scope (D10); NULL = holders with Unknown department';

COMMENT ON COLUMN "recommendations"."detection_result_id" IS 'Result it was created from; NULL when created by hand';

COMMENT ON COLUMN "recommendations"."evidence" IS 'Snapshot of the evidence at creation time (BR-13)';

COMMENT ON COLUMN "recommendations"."estimated_yearly_saving" IS 'NULL = Unknown, when the price is not known (D15)';

COMMENT ON COLUMN "recommendations"."actual_saving" IS 'Entered when marked done';

COMMENT ON COLUMN "recommendations"."notice_deadline" IS 'Last day to act before the renewal: renewal_date - notice_period_days of the contract (UC13). NULL = can be acted on at any time (monthly, pay-as-you-go)';

COMMENT ON TABLE "audit_logs" IS 'Append-only record of who changed what, with old value, new value, and time
(BR-15): license data, expenses, budgets, recommendations, users, units,
roles, permissions, and settings. The application database role has INSERT
and SELECT only on this table, so rows cannot be updated or deleted.
';

COMMENT ON COLUMN "audit_logs"."actor_id" IS 'NULL for system jobs';

COMMENT ON COLUMN "audit_logs"."action" IS 'create, update, deactivate, activate, status_change, role_change, permission_change, import ...';

COMMENT ON COLUMN "audit_logs"."entity_type" IS 'Table name of the changed row';

COMMENT ON COLUMN "audit_logs"."entity_id" IS 'id of the changed row; every table has a single-column id';

COMMENT ON COLUMN "audit_logs"."reason" IS 'Required where a rule asks for one: active budget plan (BR-08), permission change (UC22), connector value (BR-14)';

COMMENT ON COLUMN "audit_logs"."correlation_id" IS 'Request id, or sync_run / job id for system changes';

COMMENT ON TABLE "data_overrides" IS 'Staff edit of a value that came from a connector (BR-14): the edit needs a
reason and the original value is kept beside it. While an override is in
force, a sync updates original_value here and leaves the edited column.
Only entitlement lines (quantity, validity) and expenses from a billing API
can be overridden. Holders and usage of a plan with a connector cannot:
manual entry of that data is refused (UC03), so there is nothing to override.
Values are text in one format: numbers as plain decimals, dates as ISO 8601.
The source of the original value is the source column of the edited row.
Partial unique: one override in force per field
(unique on entity_type, entity_id, field_name where reverted_at is null).
App rule: the sync and a Staff edit lock the edited row (SELECT ... FOR
UPDATE) so neither overwrites the other.
';

COMMENT ON COLUMN "data_overrides"."entity_type" IS 'Table name: entitlement_lines or expenses';

COMMENT ON COLUMN "data_overrides"."original_value" IS 'Value from the connector; refreshed by each sync';

COMMENT ON COLUMN "data_overrides"."reverted_at" IS 'NULL = the override is in force';

ALTER TABLE "org_units" ADD FOREIGN KEY ("parent_id") REFERENCES "org_units" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "employees" ADD FOREIGN KEY ("org_unit_id") REFERENCES "org_units" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "role_permissions" ADD FOREIGN KEY ("role_id") REFERENCES "roles" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "role_permissions" ADD FOREIGN KEY ("permission_id") REFERENCES "permissions" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "role_permissions" ADD FOREIGN KEY ("granted_by") REFERENCES "user_accounts" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "user_accounts" ADD FOREIGN KEY ("employee_id") REFERENCES "employees" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "user_accounts" ADD FOREIGN KEY ("role_id") REFERENCES "roles" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "user_accounts" ADD FOREIGN KEY ("created_by") REFERENCES "user_accounts" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "user_sessions" ADD FOREIGN KEY ("user_account_id") REFERENCES "user_accounts" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "manager_org_units" ADD FOREIGN KEY ("user_account_id") REFERENCES "user_accounts" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "manager_org_units" ADD FOREIGN KEY ("org_unit_id") REFERENCES "org_units" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "manager_org_units" ADD FOREIGN KEY ("assigned_by") REFERENCES "user_accounts" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "system_settings" ADD FOREIGN KEY ("updated_by") REFERENCES "user_accounts" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "vendors" ADD FOREIGN KEY ("created_by") REFERENCES "user_accounts" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "provider_accounts" ADD FOREIGN KEY ("vendor_id") REFERENCES "vendors" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "provider_accounts" ADD FOREIGN KEY ("org_unit_id") REFERENCES "org_units" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "software_categories" ADD FOREIGN KEY ("parent_id") REFERENCES "software_categories" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "software_products" ADD FOREIGN KEY ("vendor_id") REFERENCES "vendors" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "software_products" ADD FOREIGN KEY ("category_id") REFERENCES "software_categories" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "software_products" ADD FOREIGN KEY ("created_by") REFERENCES "user_accounts" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "product_links" ADD FOREIGN KEY ("product_id") REFERENCES "software_products" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "license_plans" ADD FOREIGN KEY ("product_id") REFERENCES "software_products" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "license_plans" ADD FOREIGN KEY ("owner_org_unit_id") REFERENCES "org_units" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "license_plans" ADD FOREIGN KEY ("created_by") REFERENCES "user_accounts" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "contracts" ADD FOREIGN KEY ("vendor_id") REFERENCES "vendors" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "contracts" ADD FOREIGN KEY ("attachment_file_id") REFERENCES "files" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "contracts" ADD FOREIGN KEY ("created_by") REFERENCES "user_accounts" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "entitlement_lines" ADD FOREIGN KEY ("license_plan_id") REFERENCES "license_plans" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "entitlement_lines" ADD FOREIGN KEY ("provider_account_id") REFERENCES "provider_accounts" ("id") DEFERRABLE INITIALLY IMMEDIATE;

